Object.assign(quote,{extraSelections:{},sidingOther:quote.sidingOther||'steel',shipping:quote.shipping||'Shipped to your door',frameColour:quote.frameColour||'Black',glazing:quote.glazing||'Dual pane',accessory:quote.accessory||'None',finish:quote.finish||'White',layout:quote.layout||'Furnish yourself'});
