function quoteOptionValues(option,p){
 if(option.id==='siding')return quote.coverage==='Half'?[[quote.siding,quote.override?quote.overrideQty/p.panels:.5,'siding'],[quote.sidingOther,.5,'sidingOther']]:[[quote.siding,quote.override?quote.overrideQty/p.panels:1,'siding']];
 return [[quote[option.id],1,option.id],...(quote.extraSelections?.[option.id]||[]).filter((v,i,a)=>v!==quote[option.id]&&a.indexOf(v)===i).map((v,i)=>[v,1,option.id+'__'+i])];
}
function quoteOptionRows(rows,draft,more){return quoteSections.map(([section,ids])=>`<tr class="qs-category"><th colspan="${more?9:4}">${section}</th></tr>`+ids.map(id=>{
 const option=optionCatalog.find(o=>o.id===id),selected=rows.filter(r=>r.optionId===id),multi=!['model','build','frame'].includes(id);
 return selected.map((row,index)=>{const a=quoteRowAvailability(row),extra=row.key.includes('__'),choices=option.choices.filter(c=>id==='siding'||!selected.some(r=>r.key!==row.key&&r.value===c.value)),canAdd=multi&&(id==='siding'?selected.length<2:choices.length>1);
 const select=extra?`<select data-quote-extra="${id}" data-extra-index="${index-1}" aria-label="${esc(option.label+' '+(index+1))}" ${draft?'':'disabled'}>${choices.map(c=>`<option value="${esc(c.value)}" ${c.value===row.value?'selected':''}>${esc(c.label)}</option>`).join('')}</select>`:quoteSelect(row.key,row.value,choices,!draft);
 const coverage=id==='siding'?(row.key==='siding'?quoteSelect('coverage',quote.coverage,[{value:'Half',label:'Half sides'},{value:'Full',label:'Full sides'}],!draft):'<span class="qs-portion">Half sides</span>'):'';
 return `<tr><td><div class="qs-option-name"><strong>${esc(option.label)}</strong>${draft&&index===selected.length-1&&canAdd?`<button type="button" class="qs-add" data-quote-add="${id}" aria-label="Add ${esc(option.label)} selection" title="Add selection">+</button>`:''}</div></td><td><div class="qs-choice">${select}${coverage}${draft&&(extra||row.key==='sidingOther')?`<button type="button" class="qs-remove" data-quote-remove="${row.key}" aria-label="Remove ${esc(option.label+' '+(index+1))}" title="Remove selection">×</button>`:''}</div></td><td class="num">${!row.rule?'—':row.pricePending?'To quote':row.price?money(row.price):'Included'}</td><td><button class="stock-trigger" data-stock-row="${esc(row.key)}" aria-expanded="false" aria-haspopup="dialog">${tag(a.label,a.cls)}<span aria-hidden="true">↗</span></button></td>${more?quoteDetailCells(row):''}</tr>`;
 }).join('');}).join('')).join('');}
